package githubrunner

import("context";"encoding/json";"errors";"fmt";"net/http";"net/url";"strconv";"strings";"github.com/example-user/runnerhub/internal/core")
type Repository struct{ID int64 `json:"id"`;FullName string `json:"fullName"`;Private bool `json:"private"`;DefaultBranch string `json:"defaultBranch"`}
type RunnerGroup struct{ID int64 `json:"id"`;Name string `json:"name"`;Visibility string `json:"visibility"`;AllowsPublicRepositories bool `json:"allowsPublicRepositories"`;RestrictedToWorkflows bool `json:"restrictedToWorkflows"`;SelectedWorkflows []string `json:"selectedWorkflows,omitempty"`;SelectedRepositoryIDs []int64 `json:"selectedRepositoryIds,omitempty"`}
type Catalog interface{ListRepositories(context.Context,core.GitHubScope)([]Repository,error);ListRunnerGroups(context.Context,string)([]RunnerGroup,error);GetRunnerGroup(context.Context,string,int64)(RunnerGroup,error)}
type HTTPCatalog struct{client *http.Client;tokens TokenSource;base *url.URL;apiVersion string}
func NewHTTPCatalog(client *http.Client,tokens TokenSource,base string)(*HTTPCatalog,error){if tokens==nil{return nil,errors.New("token source required")};if client==nil{client=&http.Client{Timeout:30000000000}};if base==""{base="https://api.github.com"};u,err:=url.Parse(base);if err!=nil{return nil,err};if u.Scheme!="http"&&u.Scheme!="https"{return nil,errors.New("github api base url must use http or https")};return &HTTPCatalog{client:client,tokens:tokens,base:u,apiVersion:defaultAPIVersion},nil}
func(c *HTTPCatalog)ListRepositories(ctx context.Context,scope core.GitHubScope)([]Repository,error){token,err:=c.tokens.Token(ctx,scope);if err!=nil{return nil,err};var out []Repository;for page:=1;;page++{var response struct{Repositories []struct{ID int64 `json:"id"`;FullName string `json:"full_name"`;Private bool `json:"private"`;DefaultBranch string `json:"default_branch"`} `json:"repositories"`};path:="/installation/repositories?per_page=100&page="+strconv.Itoa(page);if err:=c.get(ctx,path,token,&response);err!=nil{return nil,err};for _,r:=range response.Repositories{out=append(out,Repository{ID:r.ID,FullName:r.FullName,Private:r.Private,DefaultBranch:r.DefaultBranch})};if len(response.Repositories)<100{break}};return out,nil}
func(c *HTTPCatalog)ListRunnerGroups(ctx context.Context,org string)([]RunnerGroup,error){scope:=core.GitHubScope{Kind:core.ScopeOrganization,Owner:org};token,err:=c.tokens.Token(ctx,scope);if err!=nil{return nil,err};var out []RunnerGroup;for page:=1;;page++{var response struct{RunnerGroups []RunnerGroup `json:"runner_groups"`};path:="/orgs/"+url.PathEscape(org)+"/actions/runner-groups?per_page=100&page="+strconv.Itoa(page);if err:=c.get(ctx,path,token,&response);err!=nil{return nil,err};out=append(out,response.RunnerGroups...);if len(response.RunnerGroups)<100{break}};return out,nil}
func(c *HTTPCatalog)GetRunnerGroup(ctx context.Context,org string,id int64)(RunnerGroup,error){if strings.TrimSpace(org)==""||id<=0{return RunnerGroup{},errors.New("organization and runner group id required")};scope:=core.GitHubScope{Kind:core.ScopeOrganization,Owner:org};token,err:=c.tokens.Token(ctx,scope);if err!=nil{return RunnerGroup{},err};var g RunnerGroup;if err:=c.get(ctx,"/orgs/"+url.PathEscape(org)+"/actions/runner-groups/"+strconv.FormatInt(id,10),token,&g);err!=nil{return RunnerGroup{},err};return g,nil}
func(c *HTTPCatalog)get(ctx context.Context,path,token string,out any)error{rel,err:=url.Parse(path);if err!=nil{return err};req,err:=http.NewRequestWithContext(ctx,http.MethodGet,c.base.ResolveReference(rel).String(),nil);if err!=nil{return err};req.Header.Set("Authorization","Bearer "+token);req.Header.Set("Accept","application/vnd.github+json");req.Header.Set("X-GitHub-Api-Version",c.apiVersion);resp,err:=c.client.Do(req);if err!=nil{return err};defer resp.Body.Close();if resp.StatusCode<200||resp.StatusCode>=300{return fmt.Errorf("github catalog request returned %d",resp.StatusCode)};return json.NewDecoder(resp.Body).Decode(out)}
